-- KICKOLÉ leaderboard review. Commit only — apply this on the kickole project by hand.
-- Builds on 20261021104400 / 20261021104401. Do not edit those files.
-- Nicknames are two words from private.nickname_words. The server adds II, III… when a pair is taken.
-- Insert the IP salt yourself (never commit it):
--   insert into private.app_secrets (key, value) values ('ip_hash_salt', '<long random secret>');
-- Until that row exists, per-IP limits are skipped and no address is stored.

create extension if not exists pgcrypto with schema extensions;

create table private.countries (
  code char(2) primary key check (code ~ '^[A-Z]{2}$')
);

create table private.nickname_words (
  kind text not null check (kind in ('adjective', 'noun')),
  word text not null check (word ~ '^[A-Za-z]+$'),
  primary key (kind, word)
);

create table private.period_best (
  player_id uuid not null references private.players (id) on delete cascade,
  period text not null check (period in ('day', 'week', 'month', 'year', 'all')),
  period_start date not null,
  score integer not null check (score >= 0),
  achieved_at timestamptz not null,
  primary key (player_id, period, period_start)
);
create index period_best_rank_idx on private.period_best (period, period_start, score desc, achieved_at);

create table private.run_tokens (
  token uuid primary key,
  player_id uuid not null references private.players (id) on delete cascade,
  created_at timestamptz not null default now(),
  used_at timestamptz
);
create index run_tokens_player_idx on private.run_tokens (player_id, created_at desc);

create table private.app_secrets (
  key text primary key,
  value text not null
);
comment on table private.app_secrets is
  'Rob inserts ip_hash_salt. Until then, IP rate limits are skipped and raw IPs are never stored.';

create table private.rate_limits (
  id bigint generated always as identity primary key,
  ip_hash text,
  device_id uuid,
  action text not null,
  created_at timestamptz not null default now(),
  constraint rate_limits_subject check (ip_hash is not null or device_id is not null)
);
create index rate_limits_ip_idx on private.rate_limits (ip_hash, action, created_at desc);
create index rate_limits_device_idx on private.rate_limits (device_id, action, created_at desc);

create table private.moderation_log (
  id bigint generated always as identity primary key,
  report_id bigint,
  player_id uuid,
  action text not null check (action in ('dismiss', 'hide', 'ban')),
  actor text not null default current_user,
  created_at timestamptz not null default now()
);
create index moderation_log_player_idx on private.moderation_log (player_id, created_at desc);

alter table private.players alter column nickname drop not null;
alter table private.players drop constraint players_nickname_format;
alter table private.players add constraint players_nickname_format check (
  nickname is null or (
    char_length(nickname) between 3 and 40
    and nickname ~ '^[A-Za-z]+ [A-Za-z]+( [IVXLCDM]+)?$'
  )
);
alter table private.players add column banned boolean not null default false;
alter table private.players add column deleted_at timestamptz;
alter table private.players add column renamed_at timestamptz;
alter table private.players add column last_played_at timestamptz;

alter table private.countries enable row level security;
alter table private.nickname_words enable row level security;
alter table private.period_best enable row level security;
alter table private.run_tokens enable row level security;
alter table private.app_secrets enable row level security;
alter table private.rate_limits enable row level security;
alter table private.moderation_log enable row level security;

-- nickname-words:begin
on conflict do nothing;
-- nickname-words:end

-- countries:begin
on conflict do nothing;
-- countries:end

select pb.player_id, 'all', date '1970-01-01', pb.best_score, pb.best_at
from private.player_best pb
on conflict do nothing;

select pb.player_id, 'week', pb.week_start, pb.week_score, pb.week_at
from private.player_best pb
where pb.week_start = private.week_start()
on conflict do nothing;

select pb.player_id, 'day', (pb.best_at at time zone 'UTC')::date, pb.best_score, pb.best_at
from private.player_best pb
where (pb.best_at at time zone 'UTC')::date = (now() at time zone 'UTC')::date
on conflict do nothing;

select pb.player_id, 'month', date_trunc('month', pb.best_at at time zone 'UTC')::date, pb.best_score, pb.best_at
from private.player_best pb
where date_trunc('month', pb.best_at at time zone 'UTC') = date_trunc('month', now() at time zone 'UTC')
on conflict do nothing;

select pb.player_id, 'year', date_trunc('year', pb.best_at at time zone 'UTC')::date, pb.best_score, pb.best_at
from private.player_best pb
where date_trunc('year', pb.best_at at time zone 'UTC') = date_trunc('year', now() at time zone 'UTC')
on conflict do nothing;
